using System.Text.Json;using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Settings.Entities;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Settings.UpsertSiteSetting;public sealed class UpsertSiteSettingCommandHandler(ISiteSettingRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow):ICommandHandler<UpsertSiteSettingCommand,Result<Guid>>{public async Task<Result<Guid>> HandleAsync(UpsertSiteSettingCommand c,CancellationToken ct=default){try{using var _=JsonDocument.Parse(c.ValueJson);}catch(JsonException){return Result.Failure<Guid>(ContentErrors.InvalidJson);}var site=string.IsNullOrWhiteSpace(c.SiteKey)?ContentConstants.DefaultSiteKey:c.SiteKey.Trim();var x=await repo.GetByKeyAsync(site,c.Key,ct);object? before=null;if(x is null){x=SiteSetting.Create(c.Key,c.ValueJson,c.IsPublic,site,c.ActorUserId);await repo.AddAsync(x,ct);}else{before=ContentAuditSnapshots.From(x);x.Update(c.ValueJson,c.IsPublic,c.ActorUserId);}await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.SettingUpdated,before is null?ContentAuditActions.Created:ContentAuditActions.Updated,ContentAuditEntityTypes.SiteSetting,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);await cache.RemovePublicSettingsAsync(site,ct);return Result.Success(x.Id);}}
